import {createClient} from '@supabase/supabase-js';
import {z} from 'zod';
import {rateLimit} from 'express-rate-limit';
import {AppError} from './errors.js';
const email=z.string().trim().email().max(254).transform(v=>v.toLowerCase());
const password=z.string().min(10).max(128);
const publicUser=user=>user?{id:user.id,email:user.email,name:String(user.user_metadata?.name||'').slice(0,80)}:null;
export function mountAuth(app,{url,key,origin,production=false,clientFactory=createClient}){
 const configured=Boolean(url&&key);
 const client=()=>clientFactory(url,key,{auth:{persistSession:false,autoRefreshToken:false,detectSessionInUrl:false},global:{fetch:(input,init)=>fetch(input,{...init,signal:AbortSignal.timeout(15000)})}});
 const options={httpOnly:true,secure:production,sameSite:'strict',signed:true,path:'/'};
 function cookies(res,session){if(!session?.access_token||!session.refresh_token)throw new AppError(502,'A autenticação não retornou uma sessão válida.');res.cookie('ec_access',session.access_token,{...options,maxAge:Math.min(session.expires_in||3600,86400)*1000});res.cookie('ec_refresh',session.refresh_token,{...options,maxAge:30*86400000});}
 function clear(res){res.clearCookie('ec_access',options);res.clearCookie('ec_refresh',options);}
 const limit=rateLimit({windowMs:900000,limit:20,standardHeaders:'draft-8',legacyHeaders:false,message:{error:'Muitas tentativas. Aguarde alguns minutos antes de tentar novamente.'}});
 const ready=(_req,_res,next)=>configured?next():next(new AppError(503,'O login está em configuração. Você pode continuar consultando vagas e cursos sem conta.'));
 async function sessionUser(req,res){
  if(!configured)return null;
  const c=client();const access=req.signedCookies.ec_access;const refresh=req.signedCookies.ec_refresh;
  if(access){const {data,error}=await c.auth.getUser(access);if(!error&&data?.user){req.authTokens={access_token:access,refresh_token:refresh};return publicUser(data.user);}}
  if(refresh){const {data,error}=await c.auth.refreshSession({refresh_token:refresh});if(!error&&data?.session&&data.user){cookies(res,data.session);req.authTokens=data.session;return publicUser(data.user);}}
  clear(res);return null;
 }
 const wrap=fn=>(req,res,next)=>Promise.resolve(fn(req,res)).catch(e=>next(e instanceof AppError?e:new AppError(502,'O serviço de autenticação não respondeu. Tente novamente.')));
 app.get('/api/auth/me',wrap(async(req,res)=>res.json({configured,user:await sessionUser(req,res)})));
 app.post('/api/auth/register',limit,ready,wrap(async(req,res)=>{
  const parsed=z.object({name:z.string().trim().min(2).max(80),email,password,consent:z.literal(true)}).safeParse(req.body);if(!parsed.success)throw new AppError(400,'Informe seu nome, um e-mail válido, uma senha de 10 a 128 caracteres e aceite a política de privacidade.');
  const {name,email:mail,password:pass}=parsed.data;
  const {data,error}=await client().auth.signUp({email:mail,password:pass,options:{data:{name},emailRedirectTo:origin+'/#login'}});
  if(error)throw new AppError(error.status===429?429:400,error.status===429?'Limite de e-mails atingido. Aguarde antes de tentar novamente.':'Não foi possível concluir o cadastro. Confira os dados ou tente entrar/recuperar sua conta.');
  if(data?.session){cookies(res,data.session);return res.json({user:publicUser(data.user),confirmationRequired:false});}
  res.json({user:null,confirmationRequired:true,message:'Se o cadastro puder ser concluído, você receberá um e-mail de confirmação. Confira também a caixa de spam. Se já tem conta, entre ou recupere sua senha.'});
 }));
 app.post('/api/auth/login',limit,ready,wrap(async(req,res)=>{
  const parsed=z.object({email,password:z.string().min(1).max(128)}).safeParse(req.body);if(!parsed.success)throw new AppError(400,'Informe e-mail e senha.');
  const {data,error}=await client().auth.signInWithPassword(parsed.data);
  if(error||!data?.session)throw new AppError(401,'Não foi possível entrar. Confira e-mail e senha e confirme seu e-mail antes de tentar novamente.');
  cookies(res,data.session);res.json({user:publicUser(data.user)});
 }));
 app.post('/api/auth/logout',wrap(async(req,res)=>{
  if(configured&&req.signedCookies.ec_access&&req.signedCookies.ec_refresh){try{const c=client();await c.auth.setSession({access_token:req.signedCookies.ec_access,refresh_token:req.signedCookies.ec_refresh});await c.auth.signOut({scope:'local'});}catch{}}
  clear(res);res.json({ok:true});
 }));
 app.post('/api/auth/forgot',limit,ready,wrap(async(req,res)=>{
  const parsed=z.object({email}).safeParse(req.body);if(!parsed.success)throw new AppError(400,'Informe um e-mail válido.');
  const {error}=await client().auth.resetPasswordForEmail(parsed.data.email,{redirectTo:origin+'/#recuperar'});
  if(error&&error.status===429)throw new AppError(429,'Limite de solicitações atingido. Aguarde alguns minutos.');
  if(error&&error.status>=500)throw new AppError(502,'Não foi possível enviar a recuperação agora. Tente novamente.');
  res.json({message:'Se esse e-mail estiver cadastrado, você receberá as instruções para redefinir a senha.'});
 }));
 app.post('/api/auth/recovery',limit,ready,wrap(async(req,res)=>{
  const parsed=z.object({accessToken:z.string().min(20).max(6000),refreshToken:z.string().min(5).max(1000)}).safeParse(req.body);if(!parsed.success)throw new AppError(400,'Link inválido ou expirado. Solicite outro e-mail de recuperação.');
  const c=client();const {data,error}=await c.auth.setSession({access_token:parsed.data.accessToken,refresh_token:parsed.data.refreshToken});if(error||!data?.user||!data?.session)throw new AppError(401,'Link inválido ou expirado. Solicite outro e-mail.');cookies(res,data.session);res.json({user:publicUser(data.user)});
 }));
 app.post('/api/auth/password',limit,ready,wrap(async(req,res)=>{
  const parsed=z.object({password}).safeParse(req.body);if(!parsed.success)throw new AppError(400,'Use uma senha de 10 a 128 caracteres.');
  const user=await sessionUser(req,res);if(!user)throw new AppError(401,'Sua sessão expirou. Solicite novamente a recuperação.');
  const access=req.authTokens?.access_token;const refresh=req.authTokens?.refresh_token;if(!access||!refresh)throw new AppError(401,'Reabra o link de recuperação para continuar.');
  const c=client();const setup=await c.auth.setSession({access_token:access,refresh_token:refresh});if(setup.error)throw new AppError(401,'Sessão expirada. Reabra o link de recuperação.');
  const {error}=await c.auth.updateUser({password:parsed.data.password});if(error)throw new AppError(400,'Não foi possível atualizar a senha. Escolha uma senha diferente e tente novamente.');if(setup.data?.session)cookies(res,setup.data.session);res.json({message:'Senha atualizada. Você já pode entrar com a nova senha.'});
 }));
 return {configured};
}

