function filterCourses(){const q=norm($('#course-search').value.trim()),category=$('#course-category').value;const selected=courseData.filter(c=>(category==='todas'||c.category===category)&&norm(`${c.title} ${c.description} ${c.category} ${c.provider}`).includes(q));$('#course-grid').replaceChildren(...selected.map(courseCard));$('#catalog-count').textContent=`${selected.length} ${selected.length===1?'curso encontrado':'cursos encontrados'}`;$('#course-empty').hidden=selected.length>0;}
$('#course-search').addEventListener('input',filterCourses);$('#course-category').addEventListener('change',filterCourses);$('#clear-course-filters').addEventListener('click',()=>{$('#course-search').value='';$('#course-category').value='todas';filterCourses();});
fetch('/courses.json').then(r=>{if(!r.ok)throw Error();return r.json();}).then(data=>{courseData=data.courses;filterCourses();}).catch(()=>{$('#catalog-count').textContent='Não foi possível carregar o catálogo. Atualize a página ou acesse os catálogos oficiais abaixo.';});
function authFeedback(message,error=false){const box=$('#auth-feedback');box.textContent=message;box.hidden=!message;box.classList.toggle('error',error);}
function setAuthMode(mode){authMode=mode;const register=mode==='register',forgot=mode==='forgot';$('#login-tab').classList.toggle('active',!register);$('#register-tab').classList.toggle('active',register);$('#login-tab').setAttribute('aria-pressed',String(!register));$('#register-tab').setAttribute('aria-pressed',String(register));$('#auth-name-field').hidden=!register;$('#auth-name').required=register;$('#auth-consent-field').hidden=!register;$('#auth-consent').required=register;$('#auth-password-field').hidden=forgot;$('#auth-password').required=!forgot;$('#auth-password').minLength=register?10:1;$('#auth-password').autocomplete=register?'new-password':'current-password';$('#auth-password').value='';$('#password-hint').hidden=!register;$('#auth-subtitle').textContent=register?'Crie sua conta gratuita e acompanhe seus próximos passos.':forgot?'Informe seu e-mail para receber as instruções de recuperação.':'Entre na sua conta do Emprego Certo.';$('#auth-submit').textContent=register?'Criar minha conta →':forgot?'Enviar instruções →':'Entrar na minha conta →';$('#forgot-password').textContent=forgot?'Voltar para entrar':'Esqueci minha senha';$('#forgot-password').hidden=register;$('#auth-form').hidden=false;$('#reset-form').hidden=true;authFeedback('');}
$('#login-tab').addEventListener('click',()=>setAuthMode('login'));$('#register-tab').addEventListener('click',()=>setAuthMode('register'));$('#forgot-password').addEventListener('click',()=>setAuthMode(authMode==='forgot'?'login':'forgot'));
$('#toggle-password').addEventListener('click',()=>{const p=$('#auth-password');p.type=p.type==='password'?'text':'password';$('#toggle-password').setAttribute('aria-label',p.type==='password'?'Mostrar senha':'Ocultar senha');});
function renderAccount(){const logged=Boolean(authUser);$('#signed-in-panel').hidden=!logged;$('#signed-out-panel').hidden=logged;$('#account-link').textContent=logged?'Minha conta':'Entrar ↗';$('#auth-setup-note').hidden=authConfigured;$('#auth-submit').disabled=!authConfigured;$('#auth-email').disabled=!authConfigured;$('#auth-password').disabled=!authConfigured;if(logged){$('#welcome-title').textContent=authUser.name?`Olá, ${authUser.name.split(' ')[0]}. Seu próximo passo começa aqui.`:'Seu próximo passo começa aqui.';$('#account-email').textContent=authUser.email;$('#account-avatar').textContent=(authUser.name||authUser.email||'E').slice(0,1).toUpperCase();}}
async function loadAccount(){await authReady;try{const data=await api('/auth/me');authConfigured=data.configured;authUser=data.user;renderAccount();}catch{authConfigured=false;renderAccount();authFeedback('Não foi possível conectar ao serviço de contas agora. Tente novamente em instantes.',true);}}
$('#auth-form').addEventListener('submit',async e=>{e.preventDefault();if(authBusy)return;if(!authConfigured)return authFeedback('O serviço de contas ainda precisa ser ativado. Vagas e cursos continuam disponíveis sem conta.',true);if(!await authReady)return authFeedback('Atualize a página para restabelecer a sessão.',true);const body={email:$('#auth-email').value.trim(),...(authMode==='forgot'?{}:{password:$('#auth-password').value}),...(authMode==='register'?{name:$('#auth-name').value.trim(),consent:$('#auth-consent').checked}:{})};authBusy=true;$('#auth-submit').disabled=true;authFeedback('Conectando…');try{const data=await api('/auth/'+authMode,{method:'POST',body:JSON.stringify(body)});$('#auth-password').value='';if(data.user){authUser=data.user;renderAccount();authFeedback('');toast('Você entrou na sua conta.');}else authFeedback(data.message||'Confira seu e-mail para continuar.');}catch(e){authFeedback(e.message,true);}finally{authBusy=false;$('#auth-submit').disabled=!authConfigured;}});
