$('#reset-form').addEventListener('submit',async e=>{e.preventDefault();if(authBusy)return;const pass=$('#new-password').value;if(pass!==$('#confirm-new-password').value)return authFeedback('As senhas não coincidem.',true);authBusy=true;try{const data=await api('/auth/password',{method:'POST',body:JSON.stringify({password:pass})});$('#new-password').value='';$('#confirm-new-password').value='';setAuthMode('login');authFeedback(data.message);await loadAccount();}catch(e){authFeedback(e.message,true);}finally{authBusy=false;}});
async function callbacks(){const params=new URLSearchParams(location.hash.slice(1));const access=params.get('access_token'),refresh=params.get('refresh_token'),type=params.get('type');if(!access||!refresh)return;history.replaceState(null,'',location.pathname+(type==='recovery'?'#recuperar':'#login'));route();await authReady;try{const data=await api('/auth/recovery',{method:'POST',body:JSON.stringify({accessToken:access,refreshToken:refresh})});authConfigured=true;authUser=data.user;if(type==='recovery'){$('#signed-in-panel').hidden=true;$('#signed-out-panel').hidden=false;$('#auth-form').hidden=true;$('#reset-form').hidden=false;$('#auth-subtitle').textContent='Escolha uma nova senha para sua conta.';authFeedback('');}else{renderAccount();toast('E-mail confirmado. Sua conta está conectada.');}}catch(e){authFeedback(e.message,true);}}
loadAccount().then(callbacks);

